@startuml

class Center {
  + Name : string
  + Address : string
}

class Room {
  + RoomNumber : int
  + Capacity : int
}

class Person {
  + FirstName : string
  + FamilyName : string
  + BirthDate : date
}

class Trainer {
  + Diploma : string
}

class Member {
}

class Prospect {
}

class Session {
  + Date : date
  + StartHour : time
}

class GroupSession {
  + Type : string
}

class IndividualSession {}

Center "1" *-- "1..*" Room
Room "1" -- "0..1" Session

Person "1" -- "0..*" Member
Person "1" -- "0..*" Trainer
Person "1" -- "0..*" Prospect

Trainer --|> Person
Member --|> Person
Prospect --|> Person

GroupSession --|> Session
IndividualSession --|> Session

GroupSession "*" -- "1" Trainer
Session "*" -- "0..*" Person

@enduml

